Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <queue>
#include <string>
using namespace std;

vector<int> graph[2020];
int dist_map[20][20], scan[20][20], path_count[20][20];
char grid[20][20], pattern[20][20];
int dist_grid[20][20];
int delta_x[4]={0,1,-1,0};
int delta_y[4]={1,0,0,-1};
vector<int> node_list[20][20], node_pattern[20][20];

void connect(int a, int b) {
    graph[a].push_back(b);
    graph[b].push_back(a);
}

int distance[2020], parent[2020], total_points, total_paths;

bool level_graph() {
    queue<int> q;
    for (int i=1; i<=total_points; i++) {
        if (parent[i]==0) {
            distance[i]=0;
            q.push(i);
        } else {
            distance[i]=3010;
        }
    }
    distance[0]=3010;
    while (!q.empty()) {
        int u=q.front(); q.pop();
        if (distance[u]<distance[0]) {
            for (int v_idx=0; v_idx<(int)graph[u].size(); v_idx++) {
                int v=parent[graph[u][v_idx]];
                if (distance[v]>distance[u]+1) {
                    distance[v]=distance[u]+1;
                    q.push(v);
                }
            }
        }
    }
    return distance[0]!=3010;
}

bool find_path(int x) {
    if (x==0) return true;
    for (int i=0; i<(int)graph[x].size(); i++) {
        int u=parent[graph[x][i]];
        if (distance[u]==distance[x]+1) {
            if (find_path(u)) {
                parent[x]=graph[x][i];
                parent[graph[x][i]]=x;
                return true;
            }
        }
    }
    return false;
}

int max_matching() {
    int matches=0;
    while (level_graph()) {
        for (int i=1; i<=total_points; i++) {
            if (parent[i]==0)
                matches+=find_path(i);
        }
    }
    return matches;
}

int n, t;
void process_point(int a, int b) {
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            dist_grid[i][j]=100000;
        }
    }
    queue<pair<int,int>> q;
    dist_grid[a][b]=0;
    q.push({a,b});
    while (!q.empty()) {
        auto [x,y]=q.front(); q.pop();
        for (int i=0; i<(int)node_pattern[x][y].size(); i++)
            for (int j=0; j<(int)node_list[a][b].size(); j++)
                connect(node_list[a][b][j], node_pattern[x][y][i]);
        if (dist_grid[x][y]==dist_map[x][y]) continue;
        for (int d=0; d<4; d++) {
            int nx=x+delta_x[d], ny=y+delta_y[d];
            if (scan[nx][ny]!=-1 && dist_grid[nx][ny]>dist_grid[x][y]+1 && dist_grid[x][y]+1<=dist_map[nx][ny]) {
                dist_grid[nx][ny]=dist_grid[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, t;
    cin >> n >> t;
    for (int i=1; i<=n; i++)
        for (int j=1; j<=n; j++)
            dist_map[i][j]=t;
    for (int i=1; i<=n; i++)
        cin >> grid[i]+1;
    for (int i=1; i<=n; i++)
        cin >> pattern[i]+1;
    int rx, ry;
    total_points=1; total_paths=1000;
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if (grid[i][j]=='Z'||grid[i][j]=='Y') {
                scan[i][j]=-1; dist_map[i][j]=0;
            }
            if (grid[i][j]=='Z') {
                rx=i; ry=j; dist_map[i][j]=0;
            }
            if ('0'<=grid[i][j] && grid[i][j]<='9') {
                scan[i][j]=grid[i][j]-'0';
            }
            for (int k=0; k<scan[i][j]; k++)
                node_list[i][j].push_back(total_points++);
        }
    }
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if ('0'<=pattern[i][j] && pattern[i][j]<='9') {
                path_count[i][j]=pattern[i][j]-'0';
            }
            for (int k=0; k<path_count[i][j]; k++)
                node_pattern[i][j].push_back(total_paths++);
        }
    }
    queue<pair<int,int>> q;
    q.push({rx,ry});
    while (!q.empty()) {
        auto [x,y]=q.front(); q.pop();
        for (int d=0; d<4; d++) {
            int nx=x+delta_x[d], ny=y+delta_y[d];
            if (dist_map[nx][ny]>dist_map[x][y]+1 && scan[nx][ny]!=-1) {
                dist_map[nx][ny]=dist_map[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if (scan[i][j]>0) {
                process_point(i,j);
            }
        }
    }
    cout << max_matching() << "\n";
}
